import{_t as e,it as t,n,rt as r}from"./chunks/framework.BmT8T0yb.js";var i=JSON.parse(`{"title":"Camera Tools","description":"","frontmatter":{"qt_version":"6.12.0"},"headers":[],"relativePath":"en/qgc-user-guide/fly_view/camera_tools.md","filePath":"en/qgc-user-guide/fly_view/camera_tools.md"}`),a={name:`en/qgc-user-guide/fly_view/camera_tools.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<h1 id="camera-tools" tabindex="-1">Camera Tools <a class="header-anchor" href="#camera-tools" aria-label="Permalink to “Camera Tools”">​</a></h1><p>The camera tools are used to capture still images and video, and to configure the camera.</p><p>The camera capture and configuration options depend on the connected camera. The configuration options are selected using the panel gear icon. The configuration for a simple autopilot-connected camera are shown below.</p><p>When connected to camera that supports the <a href="https://mavlink.io/en/services/camera.html" target="_blank" rel="noreferrer">MAVLink Camera Protocol</a> you can additionally configure and use other camera services that it makes available. For example, if your camera supports video mode you will be able to switch between still image capture and video mode, and start/stop recording.</p><div class="info custom-block"><p class="custom-block-title custom-block-title-default">INFO</p><p>Most of the settings that are displayed depend on the camera (they are defined in its <a href="https://mavlink.io/en/services/camera_def.html" target="_blank" rel="noreferrer">MAVLink Camera Definition File</a>).</p><blockquote><p>A few common settings at the end are hard-coded: Photo Mode (Single/Time Lapse), Photo Interval (if Time Lapse), Reset Camera Defaults (sends a reset command to the camera), Format (storage), and for a camera with a video stream, Grid Lines, Telemetry Overlay and Display Fit (under Video Display) :::</p></blockquote><h2 id="video_instrument_page" tabindex="-1">Video Stream <a class="header-anchor" href="#video_instrument_page" aria-label="Permalink to “Video Stream”">​</a></h2><p>The video page is used to enable/disable video streaming. When enabled, you can start/stop the video stream, enable a grid overlay or the <a href="./video_overlay.html#live-overlay">live telemetry overlay</a>, change how the image fits the screen, and record the video locally with QGC.</p><p>A single photo the camera can&#39;t take itself (it can&#39;t capture images, or not in video mode) is saved by QGC instead, from the video on display, to the <code>Photo</code> folder of the <a href="./../settings_view/general.html#load-save-path">Application Load/Save Path</a>. The JPEG records when it was taken and where the vehicle was (EXIF date and GPS position).</p></div>`,5)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};